fn get_min_val(a: &Vec<i8>) -> i8 {
    // Since the array is non-empty, unwrap() is safe here.
    *a.iter().min().unwrap()
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    *a.iter().max().unwrap()
}

fn nanquantile(mut a: Vec<i8>, q: i8) -> i8 {
    // Sort the vector in non-decreasing order.
    a.sort();

    // Number of elements (guaranteed >= 1).
    let n = a.len() as i32;

    // Compute the index corresponding to the q-th percentile.
    // For q = 0  -> idx = 0
    // For q = 100 -> idx = n - 1
    // Intermediate values get floor((q/100) * (n-1)).
    let idx = (q as i32 * (n - 1)) / 100;

    // Safe to index because 0 <= idx <= n-1.
    a[idx as usize]
}

